def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>This guide is about deterring, detecting and getting help, never fighting. These patents are its hardware: a pocket door brace, mechanical and battery bell alarms that sound when a door or window is opened, window guards that can be removed from inside or turned into a fire escape, and the cylinder pin lock. They run from things you can make from scrap to factory hardware you can learn to fit and repair. All are expired and free to copy. Read them with Parts 2 and 4, and remember section 2.3: every barred window needs a quick way out in a fire.</p>"
UNPATENTED = ["Tin-can and pebble trip lines, wedges under doors, thorny hedges and the watch rotation in Part 5 are traditional methods that anyone may use."]
PATENTS = [
P("US559382","f9/b7/7d/d7ebe65480bc3e/US559382.pdf","9c/e1/82/b3d68f46ab2831/US559382-drawings-page-1.png","A","1896-05-05","Charles Hoffman (Spokane, Washington)","Door-brace",
  "A simple folding brace set at the foot of an ordinary door to stop it being pushed open. It folds small enough to carry in a pocket. You can copy it in hardwood or bent strap iron for a door that has no strong lock (see section 2.1).","Fig. 1 brace applied to door bottom; Figs. 2&ndash;3 applying and folding"),
P("US55823","1a/0b/6c/57ee52e08c07ce/US55823.pdf","87/a1/86/ab8b3b54cc27c4/US55823-drawings-page-1.png","A","1866-06-26","Elliott H. Crane (Burr Oak, Michigan)","Improved door-bell and burglar-alarm",
  "An ordinary door bell with a second hammer. When the alarm is set, an arm lies across the crack between door and frame, so opening the door cocks the hammer and then lets it strike the bell. It is a purely mechanical alarm with no batteries (see section 4.2).","Bell, hammers and setting arm on base plate"),
P("US212053","c6/4b/ec/6fd01a83994e4c/US212053.pdf","dd/55/66/9c711ceee61ed5/US212053-drawings-page-1.png","A","1879-02-04","John S. Ranney (Grand Rapids, Michigan)","Combined window and door fastener and burglar-alarm",
  "A door or window lock and a burglar alarm built as one device, so the same fitting both secures the opening and warns of it being opened.","Fig. 1 perspective; Fig. 2 longitudinal section"),
P("US1168155","4d/4a/62/e6a2d431102913/US1168155.pdf","18/99/f7/59e70403d1c57e/US1168155-drawings-page-1.png","B","1916-01-11","Abraham Broune (Brooklyn, New York)","Window-guard",
  "A window safety guard that fits any ordinary window without blocking the view or the air. It can be put in place or taken out by people with no previous experience. That quick removal from inside is what section 2.3 requires of any window bar.","Guard in window frame; fixing and release details"),
P("US1333896","3f/ea/87/561bf91f3d90d4/US1333896.pdf","9f/3f/9f/b01e048bcba0ba/US1333896-drawings-page-1.png","B","1920-03-16","Isidor D. Braune (Brooklyn, New York)","Window-guard",
  "A collapsible window guard that bars the window when folded in. When swung outward it serves as a scaffold or fire escape. It shows a guard that becomes an exit instead of a trap.","Sheet 1: guard closed and extended"),
P("US9802","7c/0e/5a/01cc618373ab09/US9802.pdf","8a/57/af/2b75dd1ab2637c/US9802-drawings-page-1.png","C","1853-06-21","Augustus R. Pope (Somerville, Massachusetts)","Improvement in electro-magnetic alarms",
  "An early electric burglar alarm for a door, a window or both. A spring circuit-breaker and contact &ldquo;keys&rdquo; at the door and sash work an electromagnet and bell on the wall when either is opened. With a battery, wire and a salvaged bell, this is the basic circuit for the battery alarms in section 4.2.","Fig. 1 door and window with magnet and bell; Figs. 2&ndash;4 circuit-breaker and keys"),
P("US412563","38/bd/4c/fc9e9265506ece/US412563.pdf","9b/2c/81/31debba369c589/US412563-drawings-page-1.png","C","1889-10-08","Daniel H. Streeper (Norristown, Pennsylvania)","Electrical door-alarm",
  "A switch arm on the knob socket swings over a contact plate set in the door. When the outside knob is turned, the circuit through a battery and bell closes, giving notice inside. It is the same simple battery-and-switch alarm in a door knob.","Fig. 1 knob and lock, partly in section, with switch arm and contact"),
P("US48475","7f/9d/64/b736a3027fc5bf/US48475.pdf","9c/63/ca/59b6805c9aba20/US48475-drawings-page-1.png","C","1865-06-27","Linus Yale, Jr. (Shelburne Falls, Massachusetts)","Improvement in locks",
  "Linus Yale Jr.'s improvements to the cylinder &ldquo;pin-lock&rdquo;: a cylinder in a tumbler case, sectioned pin tumblers on springs, and the key. The sections show how the parts fit together, which helps when choosing, fitting and servicing door locks (see section 2.1).","Figs. 9&ndash;14 tumbler case and cylinder sections; Figs. 17&ndash;19 tumblers, key and springs"),
P("US482227","20/e8/59/faa086d9a50b9b/US482227.pdf","79/73/73/57ab101cc93a26/US482227-drawings-page-1.png","A","1892-09-06","William J. Conner","Door-check",
  "A chain door guard that runs across the door from one side of the frame to the other, so the door cannot be opened from outside. One end of the chain is fixed to an eye-plate on one jamb, and the free end engages a spring catch on the opposite jamb. Read with Part 2, Hardening the House.","Fig. 1 front view of door, frame and chain; Figs. 2-3 the spring catch"),
P("US412189","a5/cf/16/119ec016d5f96d/US412189.pdf","3f/56/a8/f78c47c7bb3437/US412189-drawings-page-1.png","B","1889-10-01","George Kingsland","Sash-fastener",
  "A sash lock mortised into the side of a sliding window sash. It holds the window shut, or holds it open at any height the window can be raised to. The patent stresses simple, strong working parts (see 2.2 Windows and sliding doors).","Fig. 1 the fastener let into the sash; Fig. 2 its interior"),
]
